INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne - Gouvernements des 16 Laender', 'Ministres-presidents, ministres et secretaires d''Etat des 16 Laender allemands (categorie DE-a)', 'de_pep_land_governments', 'PEP', 'https://www.baden-wuerttemberg.de', 'de-pep-land-governments', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-land-governments-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"urls":"[\\\"https://www.baden-wuerttemberg.de/de/regierung/ministerpraesident\\\",\\\"https://www.baden-wuerttemberg.de/de/regierung/mitglieder-der-landesregierung\\\",\\\"https://www.bayern.de/staatsregierung/ministerpraesident/minister-president/\\\",\\\"https://www.bayern.de/staatsregierung/kabinett/\\\",\\\"https://daten.berlin.de/datensaetze\\\",\\\"https://www.berlin.de/rbmskzl/politik/senat/senatsmitglieder/\\\",\\\"https://brandenburg.de/de/ministerpraesident/bb1.c.476536.de\\\",\\\"https://brandenburg.de/de/minister/bb1.c.476877.de\\\",\\\"https://www.rathaus.bremen.de/senat-734\\\",\\\"https://www.rathaus.bremen.de/praesidenten-des-senats-seit-1945-4308\\\",\\\"https://www.hamburg.de/politik-und-verwaltung/senat/der-hamburger-senat\\\",\\\"https://www.hamburg.de/politik-und-verwaltung/behoerden/senatskanzlei/wir-ueber-uns\\\",\\\"https://staatskanzlei.hessen.de/unser-haus/chef-der-staatskanzlei\\\",\\\"https://hessen.de/regierung/landesregierung/staatssekretaerinnen-und-staatssekretaere\\\",\\\"https://government-mv.de/seite/cabinet\\\",\\\"https://www.state-chancellery.niedersachsen.de/minister_president/curriculum-vitae-minister-president-of-lower-saxony-olaf-lies-242206.html\\\",\\\"https://www.lower-saxony.de/politics_and_state/state_government/the-lower-saxony-state-government-99165.html\\\",\\\"https://www.land.nrw/landeskabinett\\\",\\\"https://www.rlp.de/regierung/ministerrat\\\",\\\"https://www.saarland.de/stk/DE/portale/65-jahre-saarland/hintergrund/ministerpraesidenten\\\",\\\"https://www.saarland.de/mfw/DE/wir_ueber_uns/minister\\\",\\\"https://www.saarland.de/mibs/DE/institution/minister\\\",\\\"https://www.saarland.de/mibs/DE/institution/sts/sts_BubbleTabs\\\",\\\"https://www.saarland.de/mibs/DE/institution/minister/minister_BubbleTabs\\\",\\\"https://www.saarland.de/DE/politik-verwaltung/regierung/staatskanzlei-und-ministerien\\\",\\\"https://www.saarland.de/mukmav/DE/institution/ministerin\\\",\\\"https://www.saarland.de/mukmav/DE/institution/staatssekretaer\\\",\\\"https://www.saarland.de/mbk/DE/institution/ministerin/_functions/ministerin_BubbleTabs\\\",\\\"https://www.saarland.de/mbk/DE/institution/staatssekretaer/_functions/BubbleTabs-Modul/BubbleTabs\\\",\\\"https://www.saarland.de/masfg/DE/institution/hausspitze/lebenslauf_minister\\\",\\\"https://www.saarland.de/masfg/DE/institution/hausspitze/lebenslauf_staatssekret%C3%A4r\\\",\\\"https://www.staatsregierung.sachsen.de/\\\",\\\"https://www.staatsregierung.sachsen.de/regierungsmitglieder-6584.html\\\",\\\"https://sachsen-anhalt.de/politik-verwaltung/landesregierung/page/die-ministerien\\\",\\\"https://sachsen-anhalt.de/politik-verwaltung/page/ministerpraesident\\\",\\\"https://www.schleswig-holstein.de/DE/landesregierung/ministerien-behoerden\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/I\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/II/ii_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/III/iii_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/IV/iv_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/V/v_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/VI/vi_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/VII/vii_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/VIII/viii_node\\\",\\\"https://www.schleswig holstein.de/DE/landesregierung/ministerien behoerden/Staatskanzlei/staatskanzlei_node\\\",\\\"https://www.thueringen.de/\\\",\\\"https://thueringen.de/staatskanzlei/ministerpraesident\\\"]"}', 24, 12, 'Citer les sources des Laender', 'Laenderregierungen', 'Extrait les membres des cabinets des 16 Laender d''apres leurs sites officiels avec fiches de CV. Gere les URLs avec espaces en SOURCE_BROKEN sans planter.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Ministres-presidents et ministres des 16 Laender d''apres leurs sites officiels.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Ministre-pr%sident d''un Land%' AND p.dataset_name = 'de_pep_land_governments';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Ministres, senateurs et secretaires d''Etat des gouvernements des Laender.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Ministre ou s%nateur d''un gouvernement de Land%' AND p.dataset_name = 'de_pep_land_governments';
